const files = await mcpClient.callTool({
  name: "search_files",
  arguments: { query: "standup", folderId: "1A2b3C4d5E", modifiedAfter: "2026-07-01" }
});

let combinedText = "";
for (const file of files.result.matches) {
  const doc = await mcpClient.readResource({ uri: file.uri });
  combinedText += doc.contents[0].text + "\n\n";
}

// combinedText now goes to the model with a summarize instruction
